positive.prompt:
Open Report Numbers Checker's interactive workspace. Then Audit these three synthetic report claims against the supplied aggregate table. Use each claim's explicit absolute tolerance and preserve source and report references.

Use only this synthetic input:
{
  "table": {
    "metrics": [
      {
        "id": "orders",
        "label": "Synthetic orders",
        "unit": "count"
      },
      {
        "id": "visits",
        "label": "Synthetic visits",
        "unit": "count"
      }
    ],
    "periods": [
      {
        "id": "before",
        "label": "Prior period"
      },
      {
        "id": "after",
        "label": "Current period"
      }
    ],
    "cells": [
      {
        "metricId": "orders",
        "periodId": "before",
        "value": 100,
        "sourceRef": "table A1"
      },
      {
        "metricId": "orders",
        "periodId": "after",
        "value": 120,
        "sourceRef": "table A2"
      },
      {
        "metricId": "visits",
        "periodId": "before",
        "value": 300,
        "sourceRef": "table B1"
      },
      {
        "metricId": "visits",
        "periodId": "after",
        "value": 400,
        "sourceRef": "table B2"
      }
    ]
  },
  "claims": [
    {
      "id": "total",
      "lineRef": "report line 1",
      "kind": "total",
      "metricId": "orders",
      "periodIds": [
        "before",
        "after"
      ],
      "claimedValue": 220,
      "absoluteTolerance": 0
    },
    {
      "id": "growth",
      "lineRef": "report line 2",
      "kind": "percentage_change",
      "metricId": "orders",
      "fromPeriodId": "before",
      "toPeriodId": "after",
      "claimedValue": 25,
      "absoluteTolerance": 0.05
    },
    {
      "id": "ratio",
      "lineRef": "report line 3",
      "kind": "ratio",
      "numerator": {
        "metricId": "orders",
        "periodId": "before"
      },
      "denominator": {
        "metricId": "visits",
        "periodId": "before"
      },
      "scale": "percent",
      "claimedValue": 33.3,
      "absoluteTolerance": 0.05
    }
  ]
}

